package app.noir.mobile;
import android.app.AlertDialog;
import org.json.JSONObject;
import android.content.Intent;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;

final class PhoneExperience {
 static final String BUILD="Standalone · 2026-10-25";
 static String version(android.content.Context c){try{return "Noir for Android "+c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName+" · "+BUILD;}catch(Exception e){return "Noir for Android · "+BUILD;}}
 static boolean trackerOnly(DataStore data){return data.playbackFlag("historyOnly",false);}
 static void choose(MainActivity a,boolean track){a.data.phoneSetting("historyOnly",track);a.data.pref("experienceChosen",true);a.page=track?"History":"Home";a.detail="";a.premium.historyView="Up next";a.render();}
 static void welcome(MainActivity a){a.heading("Your cinema, on your phone.");a.paragraph("Your history, your lists, your next episode. Make Noir yours.");a.body.addView(a.button("Just track what I watch",()->choose(a,true),true));a.paragraph("Watch anywhere. Log here. Keep your viewing story with you.");a.body.addView(a.button("Watch & track",()->{choose(a,false);a.startActivity(new Intent(a,DiscoverActivity.class));},false));a.body.addView(a.button("Import history or restore a backup",()->a.startActivity(new Intent(a,HistoryToolsActivity.class)),false));}
 static View profileHeader(MainActivity a){JSONObject me;try{me=a.data.profiles.get(a.data.profileId);}catch(RuntimeException e){me=new JSONObject();}String name=me.optString("name").trim();int color=MainActivity.GOLD;try{color=android.graphics.Color.parseColor(me.optString("color","#E5C185"));}catch(RuntimeException ignored){}if(name.isEmpty())name=a.data.prefs().optString("displayName",a.browsingSettings().optString("profileName",Loc.t("You"))).trim();if(name.isEmpty())name=Loc.t("You");LinearLayout card=new LinearLayout(a);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(a.dp(18),a.dp(20),a.dp(18),a.dp(20));card.setBackground(MainActivity.bg(0xff241f19,a.dp(22)));TextView avatar=a.text(name.substring(0,name.offsetByCodePoints(0,1)).toUpperCase(java.util.Locale.getDefault()),25,MainActivity.BLACK);avatar.setTypeface(null,Typeface.BOLD);avatar.setGravity(Gravity.CENTER);avatar.setBackground(MainActivity.bg(color,a.dp(30)));card.addView(avatar,new LinearLayout.LayoutParams(a.dp(60),a.dp(60)));LinearLayout info=a.column();info.setPadding(a.dp(16),0,a.dp(10),0);TextView title=a.text(name,24,MainActivity.WHITE);title.setTypeface(null,Typeface.BOLD);info.addView(title);info.addView(a.text(me.optString("pcProfileName").isEmpty()?Loc.t("Only on this phone · tap to switch or add profiles"):Loc.f("Linked to %s on your PC · tap to manage",me.optString("pcProfileName")),12,MainActivity.MUTED));card.addView(info,new LinearLayout.LayoutParams(0,-2,1));card.addView(a.text("›",24,MainActivity.GOLD));card.setContentDescription(Loc.t("Profile"));card.setOnClickListener(v->onProfileTap(a));Motion.card(card);return card;}
 static void onProfileTap(MainActivity a){a.startActivity(new android.content.Intent(a,ProfilesActivity.class));}
 static void settings(MainActivity a){a.heading("Your space");a.body.addView(profileHeader(a));a.heading("The way you watch");
  row(a,"◉","Experience",trackerOnly(a.data)?"Just track what I watch":"Watch & track",()->new AlertDialog.Builder(a).setTitle(Loc.t("Experience")).setSingleChoiceItems(new String[]{Loc.t("Just track what I watch"),Loc.t("Watch & track")},trackerOnly(a.data)?0:1,(d,n)->{d.dismiss();choose(a,n==0);}).setNegativeButton(Loc.t("Cancel"),null).show());
  row(a,"▶","Playback","Autoplay, intros and credits",()->playback(a));a.body.addView(PhonePreview.settingsRow(a));row(a,"≡","Subtitles","Your default subtitle language",()->subtitles(a));
  if(!trackerOnly(a.data)){row(a,"↓","Downloads","Saved videos on this phone",()->a.startActivity(new Intent(a,DownloadHubActivity.class)));a.body.addView(DownloadHubActivity.pickupRow(a));row(a,"⌁","Streaming","Your AIOStreams connection",()->a.startActivity(new Intent(a,PhoneDownloadSettingsActivity.class)));}
  a.heading("Your library & history");row(a,"◷","History tools","Import, export and backup here",()->a.startActivity(new Intent(a,HistoryToolsActivity.class)));row(a,"♡",TasteActivity.label(),Loc.t("Friend cards are saved only in this profile. Delete them whenever you like."),()->TasteActivity.open(a));a.body.addView(PhoneCatchUp.settingsRow(a));row(a,"⇄","Connections","History services and sync",()->{a.page="Connections";a.render();});row(a,"▣","Your PC",a.data.paired()?"Optional sync is connected":"Optional sync with Windows",()->pc(a));
  a.heading("Make it yours");row(a,"ع","Language",Loc.arabic?"العربية":"English",()->new AlertDialog.Builder(a).setTitle(Loc.t("Language")).setItems(new String[]{"English","العربية"},(d,n)->a.setLanguage(n==0?"en":"ar")).show());row(a,"ⓘ","About","Noir for Android",()->new AlertDialog.Builder(a).setTitle(Loc.t("About")).setMessage(version(a)+"\n\n"+Loc.t("Metadata: Cinemeta and TVmaze. Playback: VideoLAN LibVLC. Artwork belongs to its owners.")).setPositiveButton(Loc.t("OK"),null).show());
 }
 static void row(MainActivity a,String icon,String title,String subtitle,Runnable act){LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(a.dp(14),a.dp(13),a.dp(14),a.dp(13));row.setBackground(MainActivity.bg(MainActivity.PANEL,a.dp(14)));TextView glyph=a.text(icon,21,MainActivity.GOLD);glyph.setGravity(Gravity.CENTER);row.addView(glyph,new LinearLayout.LayoutParams(a.dp(34),a.dp(36)));LinearLayout info=a.column();info.setPadding(a.dp(12),0,a.dp(8),0);TextView name=a.text(title,15,MainActivity.WHITE);name.setTypeface(null,Typeface.BOLD);info.addView(name);info.addView(a.text(subtitle,11,MainActivity.MUTED));row.addView(info,new LinearLayout.LayoutParams(0,-2,1));row.addView(a.text("›",20,MainActivity.MUTED));row.setOnClickListener(v->act.run());row.setContentDescription(Loc.t(title));Motion.card(row);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,a.dp(6));a.body.addView(row,p);}
 static void playback(MainActivity a){PlayerPrefs.settings(a,a.data);}
 static String[] localized(String[] values){String[] result=values.clone();for(int n=0;n<result.length;n++)result[n]=Loc.t(result[n]);return result;}
 static void subtitles(MainActivity a){String[] values={"English","Arabic","Off"};new AlertDialog.Builder(a).setTitle(Loc.t("Subtitles")).setSingleChoiceItems(localized(values),java.util.Arrays.asList(values).indexOf(a.data.defaultSubtitleLanguage()),(d,n)->{a.data.phoneSetting("subtitles",values[n]);d.dismiss();}).setNeutralButton(Loc.t("Subtitle source"),(d,w)->a.startActivity(new android.content.Intent(a,PhoneDownloadSettingsActivity.class))).setNegativeButton(Loc.t("Cancel"),null).show();}
 static void pc(MainActivity a){String[] options=a.data.paired()?new String[]{"Sync now","Pair again / update PC address","Downloads on my PC"}:new String[]{"Pair with my PC"};new AlertDialog.Builder(a).setTitle(Loc.t("Your PC")).setItems(localized(options),(d,n)->{if(!a.data.paired()||n==1)a.pairInput();else if(n==0)a.sync(true);else a.startActivity(new Intent(a,PcDownloadsActivity.class));}).setNegativeButton(Loc.t("Done"),null).show();}
}
